from typing import Mapping, Optional, Tuple, List


def heaviest_route(limits: Mapping[str, Mapping[str, int]], src: str, dst: str) -> Optional[Tuple[int, List[str]]]:
    if src == dst:
        raise ValueError("src == dst")
    if src not in limits:
        raise KeyError(f"src {src} not in limits")
    if dst not in limits:
        raise KeyError(f"dst {dst} not in limits")

    # PQ: (-load, edges, path)
    pq = [(-float('inf'), 0, [src])]
    # best_load[u] = max bottleneck capacity found so far
    best_load = {node: -1 for node in limits}
    best_load[src] = float('inf')

    while pq:
        neg_load, edges, path = heapq.heappop(pq)
        load = -neg_load
        u = path[-1]

        if u == dst:
            return (int(load), path)

        if load < best_load[u]:
            continue

        for v, weight in limits.get(u, {}).items():
            new_load = min(load, weight)
            if new_load > best_load.get(v, -1):
                best_load[v] = new_load
                heapq.heappush(pq, (-new_load, edges + 1, path + [v]))
            elif new_load == best_load.get(v, -1):
                # Even if load is same, we might find a path with fewer edges or better lexicographical order
                # However, in a standard max-min path, once we find the max load, any path with the same load
                # but more edges is strictly worse. To properly handle tie-breaks for the SAME max load,
                # we should explore paths that maintain that load.
                # To avoid infinite loops and redundant work, we only push if it's potentially better.
                # But since we want fewest edges, we can just push it and let the PQ handle it.
                # To prevent exponential blowup, we only allow the same load if edges are fewer.
                # Actually, the most reliable way for this specific set of tie-breakers is to
                # track the best (load, -edges, -path) seen so far.
                heapq.heappush(pq, (-new_load, edges + 1, path + [v]))

    return None
"}}}
